/* ============================================================
   أطياب الجاسم (React) — تحديث مخزون الكتالوجات (catalogStock)

   المشكلة: قوائم المنتجات تُجلب مرة واحدة وتبقى (CACHE-HIT)،
   فمن يشتري 4 قطع يرى المخزون القديم (10 بدل 6) حتى تحديث الصفحة.

   ★ v17-S1: refreshCatalogStock(dispatch) تُحدّث الكمية/النشاط فقط
     (دمج بلا صور ولا نصوص — فلا وميض) عند كل دخول، مع منع الطلبات
     المتزامنة المكررة فقط (رحلة شبكة واحدة مشتركة + علم لكل شريحة).
     البيانات الثابتة (أسعار/منتجات جديدة) بقوائم كاملة كل 30 دقيقة.
     · تُنادى عند: دخول صفحة منتج، دخول العربة، دخول قوائم
       العرض — وبإلحاح (force) بعد إتمام طلب مباشرة.
     · حين يوفّر الباك endpoint الكميات الخفيف
       (GET /api/products/stock — انظر رسالة الباك) يُستبدل
       مصدر الجلب داخل productsFactory فقط، وهنا لا يتغيّر شيء.
   ============================================================ */

import { refreshPerfumesStock, getAllPerfumes } from "./slices/perfumesSlice.js";
import { refreshOudsStock, getAllOuds } from "./slices/oudsSlice.js";
import { refreshIncensesStock, getAllIncenses } from "./slices/incensesSlice.js";
/* ★ R23: مخزون «باقي المنتجات» — نفس المسار الخفيف المشترك */
import { refreshMistsStock, getAllMists } from "./slices/mistsSlice.js";
import { refreshLotionsStock, getAllLotions } from "./slices/lotionsSlice.js";
import { refreshMukhamariaStock, getAllMukhamaria } from "./slices/mukhamariaSlice.js";
import { refreshHairStock, getAllHair } from "./slices/hairSlice.js";

/* ★ إعادة تحميل كاملة عند انتهاء الصلاحية (البند 12): المخزون وحده
   لا يجلب الأسعار والمنتجات الجديدة — كل 30 دقيقة قوائم كاملة. */
const FULL_TTL_MS = 30 * 60 * 1000;
const lastFull = { perfumes: Date.now(), ouds: Date.now(), incenses: Date.now(), mists: Date.now(), lotions: Date.now(), mukhamaria: Date.now(), hair: Date.now() };
/* ★ #7: منع الطلبات المتزامنة المكررة للقوائم الكاملة */
const fullFlight = {};

export function refreshCatalogStock(dispatch, opts) {
  const force = !!(opts && opts.force);
  const now = Date.now();
  const jobs = [
    ["perfumes", getAllPerfumes, refreshPerfumesStock],
    ["ouds", getAllOuds, refreshOudsStock],
    ["incenses", getAllIncenses, refreshIncensesStock],
    ["mists", getAllMists, refreshMistsStock],
    ["lotions", getAllLotions, refreshLotionsStock],
    ["mukhamaria", getAllMukhamaria, refreshMukhamariaStock],
    ["hair", getAllHair, refreshHairStock]
  ];
  try {
    jobs.forEach(function (j) {
      const key = j[0];
      const needFull = force || now - (lastFull[key] || 0) > FULL_TTL_MS;
      if (needFull) {
        /* ★ #7: force فعلي + dedup — لا طلبين متزامنين لنفس الشريحة */
        if (fullFlight[key]) return;
        try {
          const p = dispatch(j[1]({ force: true }));
          if (p && typeof p.then === "function") {
            fullFlight[key] = true;
            /* ★ R10: ختم النجاح بعد fulfilled فقط — dispatch(thunk) يحل
               الوعد حتى مع rejected action، فالاعتماد على then وحده سجّل
               فشل الشبكة نجاحاً. unwrap يرفض عند rejected. */
            const done = (typeof p.unwrap === "function") ? p.unwrap() : p;
            done.then(function () {
              /* ★ #7: وقت النجاح عند النجاح فقط — لا مجرد الإرسال */
              lastFull[key] = Date.now();
              fullFlight[key] = false;
            }, function () {
              fullFlight[key] = false;
            });
          } else {
            lastFull[key] = Date.now();
          }
        } catch (e) {
          fullFlight[key] = false;
        }
      } else {
        dispatch(j[2](force));
      }
    });
  } catch (e) {
    /* تحديث تجميلي — فشله لا يوقف شيئاً */
  }
}
/* ★ #7: حالة فشل تحديث التوفر — تُستخدم في قرار الشراء */
export function lastFullAt() {
  return Object.assign({}, lastFull);
}
