/* ============================================================
   أطياب الجاسم (React) — صفحة العربة (TrolleyPage)

   تستدعي ListProductCard و SummaryProduct بوضع «السلة» (trolley) —
   لا وضع الأمنيات — لأن وضع السلة يمتلك خيارات إضافية: (+/−) للكمية،
   الحذف، وزر إتمام الدفع المدمج أسفل الفاتورة.

   ★ لا كوبون ولا اختيار طريقة هنا (أُزيلا قولاً واحداً): الكوبون وطريقة
     الدفع في خطوة الدفع داخل Checkout — فتبقى الصفحة بطول المنتجات.

   ★ الأرقام (المجموع الفرعي · خصم العروض · الشحن · الضريبة · الإجمالي)
     من selectors.js — لا حساب داخل الصفحة.
   ★ الحالة كلها في Redux (cartSlice) وتُزامَن مع العربة على الخادم (Basket).
   ============================================================ */

import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { PATHS } from "../routes.js";
import { usePageMeta } from "../usePageMeta.js";
import { useAppDispatch, useAppSelector } from "../redux/hooks.js";
import { selectCartTotals, selectCartCount } from "../redux/selectors.js";
import { cartActions, clearTrolley, pullBasket, recoverPendingPurchase } from "../redux/slices/cartSlice.js";
import { selectSupport } from "../redux/slices/settingsSlice.js";
import { refreshCatalogStock } from "../redux/catalogStock.js";
import { ATYAB_byId } from "../data/products.js";
import "../components/Skeletons/Skeletons.css";
import { getAllPerfumes, selectPerfumesStatus } from "../redux/slices/perfumesSlice.js";
import { getAllOuds, selectOudsStatus } from "../redux/slices/oudsSlice.js";
import { getAllIncenses, selectIncensesStatus } from "../redux/slices/incensesSlice.js";
/* ★ R23: تفاصيل الأصناف الجديدة في العربة */
import { getAllMists, selectMistsStatus } from "../redux/slices/mistsSlice.js";
import { getAllLotions, selectLotionsStatus } from "../redux/slices/lotionsSlice.js";
import { getAllMukhamaria, selectMukhamariaStatus } from "../redux/slices/mukhamariaSlice.js";
import { getAllHair, selectHairStatus } from "../redux/slices/hairSlice.js";
import { getOffers, selectOffersStatus } from "../redux/slices/offersSlice.js";
import { signOutEverywhere } from "../api/auth.js";
import { uiActions } from "../redux/slices/uiSlice.js";
import ListProductCard from "../components/Product/ListProductCard.jsx";
import SummaryProduct from "../components/Product/SummaryProduct.jsx";
import { Icon } from "../components/Source/Icons.jsx";

/* ------------------------------------------------------------
   هيكل تحميل العربة — يُعرض عند الدخول حتى تصل منتجات الخادم
   المحفوظة (سحب السلة). CSS خالص من Skeletons.css بلا ملف جديد.
   ------------------------------------------------------------ */
function CartSkeleton() {
  const rows = [0, 1, 2];
  return (
    <div className="ct-grid" role="status" aria-live="polite" aria-label="جارٍ تحميل العربة">
      <div className="ct-items">
        {rows.map(function (i) {
          return (
            <div className="sk-row" key={i} style={{ padding: "14px 0" }}>
              <span className="sk-block sk-avatar sk-circle" />
              <span style={{ flex: 1, display: "grid", gap: "10px" }}>
                <span className="sk-block sk-line" />
                <span className="sk-block sk-line short" />
                <span className="sk-block sk-line tiny" />
              </span>
            </div>
          );
        })}
      </div>
      <aside className="ct-aside">
        <span className="sk-block sk-line" />
        <span className="sk-block sk-line short" />
        <span className="sk-block sk-btn" style={{ marginTop: "12px" }} />
      </aside>
    </div>
  );
}

export default function TrolleyPage() {
  usePageMeta({ route: "cart", titleAr: "عربة التسوق", titleEn: "Shopping cart" });

  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const totals = useAppSelector(selectCartTotals);
  const rawCount = useAppSelector(selectCartCount);
  const rawRows = useAppSelector(function (s) {
    return (s.cart && s.cart.rows) || [];
  });
  /* ★ صفوف لا يعرفها الكتالوج الحالي (عروض قديمة/معرّفات ميتة):
     لا تُعرض في الشبكة (بلا اسم/صورة) لكنها تُعدّ في الشارة —
     نعرضها قسماً مستقلاً بأزرار إزالة بدل لغز «شارة بلا منتجات». */
  let unknownRows = [];
  try {
    unknownRows = rawRows.filter(function (r) {
      return r && !ATYAB_byId(Number(r.id));
    });
  } catch (e) {
    unknownRows = [];
  }
  const basketStale = useAppSelector(function (s) {
    return !!(s.cart && s.cart.basketStale);
  });
  const syncError = useAppSelector(function (s) {
    return !!(s.cart && s.cart.syncError);
  });
  const removedNotice = useAppSelector(function (s) {
    return (s.cart && s.cart.removedNotice) || null;
  });
  const support = useAppSelector(selectSupport);
  const customerId = useAppSelector(function (s) {
    return (s.user && s.user.auth && s.user.auth.customerId) || null;
  });
  const language = useAppSelector(function (s) {
    return (s.ui && s.ui.language) || "ar";
  });

  /* ★ الكتالوج (تفاصيل المنتجات: اسم/سعر/صورة) يُحمَّل في صفحات
     المنتجات فقط — والدخول المباشر للعربة كان يجده فارغاً فيُحكم على
     كل صف «غير معروف» خطأً. سلة الخادم تحفظ معرفات وكميات فقط، فنجلب
     الكتالوج هنا أيضاً (الـthunks تتجاهل المحمّل — CACHE-HIT). */
  const perfumesStatus = useAppSelector(selectPerfumesStatus);
  const oudsStatus = useAppSelector(selectOudsStatus);
  const incensesStatus = useAppSelector(selectIncensesStatus);
  const offersStatus = useAppSelector(selectOffersStatus);
  const mistsStatus = useAppSelector(selectMistsStatus);
  const lotionsStatus = useAppSelector(selectLotionsStatus);
  const mukhamariaStatus = useAppSelector(selectMukhamariaStatus);
  const hairStatus = useAppSelector(selectHairStatus);
  const catalogLoading = [perfumesStatus, oudsStatus, incensesStatus, offersStatus, mistsStatus, lotionsStatus, mukhamariaStatus, hairStatus].some(function (st) {
    return st === "idle" || st === "loading";
  });
  /* ★ السحب عند فتح العربة: المنتجات تظهر فوراً مع أول زيارة للحساب
     الجديد، لا بعد إضافة منتج. مرة واحدة لكل حساب. */
  const [pulling, setPulling] = useState(false);
  useEffect(
    function () {
      let alive = true;
      let timer = 0;
      if (customerId) {
        /* ★ هيكل التحميل حتى تصل منتجات الخادم المحفوظة — مع مهلة أمان
           10ث لئلا يعلق الهيكل إن تعطل السحب. الموجود محلياً يُعرض فوراً. */
        setPulling(true);
        timer = setTimeout(function () { if (alive) setPulling(false); }, 10000);
        /* ★ FE33: استرداد ما بعد الدفع دون Return أولاً، ثم السحب. */
        Promise.resolve(dispatch(recoverPendingPurchase(Number(customerId)))).then(function () {
          Promise.resolve(dispatch(pullBasket())).then(function () {
            if (timer) clearTimeout(timer);
            if (alive) setPulling(false);
          }, function () {
            if (timer) clearTimeout(timer);
            if (alive) setPulling(false);
          });
        }, function () {
          Promise.resolve(dispatch(pullBasket())).then(function () {
            if (timer) clearTimeout(timer);
            if (alive) setPulling(false);
          }, function () {
            if (timer) clearTimeout(timer);
            if (alive) setPulling(false);
          });
        });
      }
      /* ★ تفاصيل الصفوف من الكتالوج — نجلبه هنا للضيف والعضو معاً */
      dispatch(getAllPerfumes());
      dispatch(getAllOuds());
      dispatch(getAllIncenses());
      dispatch(getOffers());
      dispatch(getAllMists());
      dispatch(getAllLotions());
      dispatch(getAllMukhamaria());
      dispatch(getAllHair());
      /* ★ v17-S1: مخزون خفيف عند كل دخول للعربة (dedupe للمتزامن
         فقط): الكميات المعروضة طازجة قبل الدفع */
      refreshCatalogStock(dispatch);
      return function () { alive = false; if (timer) clearTimeout(timer); };
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [customerId]
  );

  function reLogin() {
    signOutEverywhere(dispatch);
    dispatch(
      uiActions.toastShown(
        language === "en"
          ? "Please log in again to sync your cart."
          : "سجّل الدخول مجدداً لمزامنة عربتك."
      )
    );
    navigate(PATHS.login + "?returnTo=" + encodeURIComponent(PATHS.cart));
  }

  return (
    <section className="container view ct" id="cartView">
      <div className="ct-top">
        <Link className="ct-back" to={PATHS.perfumes}>
          <Icon name="back" strokeWidth={2} />
          <span>متابعة التسوق</span>
        </Link>
        <span className="ct-crumb">
          الرئيسية / <b>عربة التسوق</b>
        </span>
      </div>

      <header className="ct-head">
        <span className="eyebrow">طلبك</span>
        <h1>
          عربة <span className="gold-text">التسوق</span>
        </h1>
        {/* ★ الحساب يتيم عند الخادم (404): العربة المحلية تعمل،
           لكن المزامنة متوقفة — نطلب إعادة الدخول بحساب موجود. */}
        {basketStale ? (
          <div className="ct-empty" style={{ padding: "16px" }}>
            <h3>حسابك غير موجود على الخادم</h3>
            <p>عربتك محفوظة على جهازك ({rawCount} قطعة). سجّل الدخول مجدداً بحساب موجود لمزامنتها وإتمام الدفع.</p>
            <div className="wl-empty-actions">
              <button className="btn-primary" type="button" onClick={reLogin}>
                تسجيل الدخول مجدداً
              </button>
            </div>
          </div>
        ) : null}
        {/* ★ فشل المزامنة (شبكة/خادم): النسخة المحلية معروضة —
           زر إعادة محاولة بدل الفشل الصامت. */}
        {syncError && !basketStale ? (
          <div className="ct-empty" style={{ padding: "16px", borderColor: "#b3541e" }}>
            <h3>تعذّرت مزامنة العربة مع الخادم</h3>
            <p>المعروض نسختك المحفوظة على جهازك. تحقق من الاتصال ثم أعد المحاولة — ولن تفقد أي قطعة.</p>
            <div className="wl-empty-actions">
              <button className="btn-primary" type="button" onClick={function () { dispatch(pullBasket()); }}>
                إعادة المحاولة
              </button>
            </div>
          </div>
        ) : null}
        {/* ★ منتج نُزع لنفاد مخزونه رسمياً: إزالة + حجز — لا حذف صامت */}
        {removedNotice && removedNotice.name ? (function () {
          const waText = language === "en"
            ? "Hello, I want to reserve: " + (removedNotice.nameEn || removedNotice.name)
            : "السلام عليكم، أريد حجز المنتج: " + removedNotice.name;
          const waHref = support && support.whatsappDigits
            ? "https://wa.me/" + support.whatsappDigits + "?text=" + encodeURIComponent(waText)
            : null;
          return (
            <div className="ct-empty" style={{ padding: "16px", borderColor: "#b3541e" }}>
              <h3>تمت إزالة «{language === "en" ? (removedNotice.nameEn || removedNotice.name) : removedNotice.name}» من العربة</h3>
              <p>نفدت الكمية رسمياً — أزلناه من عربتك. يمكنك حجزه ليصلك فور توفره.</p>
              <div className="wl-empty-actions">
                {waHref ? (
                  <a className="btn-primary" href={waHref} target="_blank" rel="noopener noreferrer">
                    انقر للحجز عبر واتساب
                  </a>
                ) : null}
                <button className="btn-ghost" type="button" onClick={function () { dispatch(cartActions.stockRemovedSeen()); }}>
                  فهمت
                </button>
              </div>
            </div>
          );
        })() : null}
        <p className="ct-sub">
          راجع قطعك وعدّل الكميات، ثم اضغط «إتمام الدفع» — الكوبون وطريقة الدفع
          بانتظارك في خطوة الدفع.
        </p>

        {totals.count > 0 ? (
          <div className="ct-actions">
            <span className="ct-count">
              <span className="ct-count-ic">
                <Icon name="cart" strokeWidth={1.8} />
              </span>
              <b>{totals.count}</b> قطعة في العربة
            </span>
            <button className="ct-clear" type="button" onClick={function () { dispatch(clearTrolley()); }}>
              <Icon name="trash" strokeWidth={1.8} />
              <span>تفريغ العربة</span>
            </button>
          </div>
        ) : null}
      </header>

      {(pulling || catalogLoading) && totals.count === 0 ? (
        <CartSkeleton />
      ) : totals.count === 0 && rawCount > 0 ? (
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="cart" strokeWidth={1.6} />
          </span>
          {unknownRows.length ? (
            <div>
              <h3>قطع غير معروفة في الكتالوج ({unknownRows.length})</h3>
              <p>عربتك محفوظة ({rawCount} قطعة) لكن الكتالوج الحالي لا يعرفها — أُخفيت أو نفدت بعد إضافتها، أو أُضيفت من عروض قديمة ولا يقبلها الخادم.</p>
              <p><b>هذا العرض لم يعد متوفراً — للحجز كلم الواتساب.</b></p>
              {support && support.whatsappDigits ? (
                <div className="wl-empty-actions" style={{ justifyContent: "center" }}>
                  <a
                    className="btn-primary"
                    href={"https://wa.me/" + support.whatsappDigits + "?text=" + encodeURIComponent((language === "en" ? "Hello, items in my cart are no longer available and I want to reserve them: " : "السلام عليكم، قطع في عربتي لم تعد متوفرة وأريد حجزها: ") + unknownRows.map(function (r) { return "#" + r.id + " × " + r.qty; }).join(", "))}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    {language === "en" ? "Reserve via WhatsApp" : "احجز عبر واتساب"}
                  </a>
                </div>
              ) : null}
              {unknownRows.map(function (r) {
                return (
                  <div className="wl-empty-actions" key={r.id} style={{ alignItems: "center", justifyContent: "center" }}>
                    <span className="ct-count">#{r.id} × {r.qty}</span>
                    <button
                      className="btn-ghost"
                      type="button"
                      onClick={function () { dispatch(cartActions.removeRow(Number(r.id))); }}
                    >
                      إزالة
                    </button>
                  </div>
                );
              })}
            </div>
          ) : (
            <div>
              <h3>نُحمّل منتجاتك…</h3>
              <p>عربتك محفوظة ({rawCount} قطعة) — ننتظر وصول قائمة المنتجات من الخادم لعرضها.</p>
            </div>
          )}
        </div>
      ) : totals.count === 0 ? (
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="cart" strokeWidth={1.6} />
          </span>
          <h3>العربة فارغة</h3>
          <p>لم تُضف أي قطعة بعد. تصفّح العطور والبخور واضغط «أضف للعربة» لتظهر قطعك هنا مع الفاتورة.</p>
          <div className="wl-empty-actions">
            <Link className="btn-primary" to={PATHS.perfumes}>
              تصفّح العطور
            </Link>
            <Link className="btn-ghost" to={PATHS.incense}>
              تصفّح البخور
            </Link>
          </div>
        </div>
      ) : (
        <div className="ct-grid">
          <div className="ct-items">
            {totals.rows.map(function (row) {
              return <ListProductCard mode="trolley" product={row.product} qty={row.qty} note={row.serverNote} key={row.id} />;
            })}
            {/* ★ معرّفات ميتة: تُعدّ في الشارة ولا تُعرض — أزلها وأعد الإضافة من الصفحة */}
            {unknownRows.length ? (
              <div className="ct-empty" style={{ padding: "16px" }}>
                <h3>قطع غير معروفة في الكتالوج ({unknownRows.length})</h3>
                <p>أُخفيت أو نفدت بعد إضافتها، أو أُضيفت من عروض قديمة ولا يتعرف عليها الخادم — <b>هذا العرض لم يعد متوفراً، للحجز كلم الواتساب.</b></p>
                {support && support.whatsappDigits ? (
                  <div className="wl-empty-actions" style={{ justifyContent: "flex-start" }}>
                    <a
                      className="btn-primary"
                      href={"https://wa.me/" + support.whatsappDigits + "?text=" + encodeURIComponent((language === "en" ? "Hello, items in my cart are no longer available and I want to reserve them: " : "السلام عليكم، قطع في عربتي لم تعد متوفرة وأريد حجزها: ") + unknownRows.map(function (r) { return "#" + r.id + " × " + r.qty; }).join(", "))}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      {language === "en" ? "Reserve via WhatsApp" : "احجز عبر واتساب"}
                    </a>
                  </div>
                ) : null}
                {unknownRows.map(function (r) {
                  return (
                    <div className="wl-empty-actions" key={r.id} style={{ alignItems: "center" }}>
                      <span className="ct-count">#{r.id} × {r.qty}</span>
                      <button
                        className="btn-ghost"
                        type="button"
                        onClick={function () { dispatch(cartActions.removeRow(Number(r.id))); }}
                      >
                        إزالة
                      </button>
                    </div>
                  );
                })}
              </div>
            ) : null}
          </div>

          <aside className="ct-aside">
            <SummaryProduct mode="trolley" />
          </aside>
        </div>
      )}
    </section>
  );
}
